select throws_ok($$insert into public.screen_groups(tenant_id,name,is_internal)values('10000000-0000-4000-8000-000000003301','Forged hidden group',true)$$,'42501','internal LED target is command owned','raw authenticated writer cannot forge internal classification');
select throws_ok($$update public.screen_groups set is_internal=false where tenant_id='10000000-0000-4000-8000-000000003301'and is_internal$$,'42501','internal LED target is command owned','raw authenticated writer cannot unhide command-owned group');
select set_config('veyocast.ledscores_target_write_context','true',true);
select throws_ok($$insert into public.screen_group_memberships(tenant_id,screen_group_id,screen_id)select '10000000-0000-4000-8000-000000003301',id,'30000000-0000-4000-8000-000000003302'from public.screen_groups where tenant_id='10000000-0000-4000-8000-000000003301'and is_internal$$,'42501','internal LED target is command owned','a forged session GUC cannot change internal memberships');
select set_config('test.source_moment_revision',(select revision::text from public.ledscores_goal_alerts where id=current_setting('test.source_moment_id')::uuid),true);
select set_config('test.source_moment_published',public.publish_ledscores_goal_alert_v1('10000000-0000-4000-8000-000000003301',current_setting('test.source_moment_id')::uuid,current_setting('test.source_moment_revision')::integer,'50000000-0000-4000-8000-000000003342')::text,true);
select is(current_setting('test.source_moment_published')::jsonb->>'outcome','published','explicit immutable publication activates direct targets');
select is((select count(*)from public.screen_group_memberships m join public.screen_groups g on g.tenant_id=m.tenant_id and g.id=m.screen_group_id where m.tenant_id='10000000-0000-4000-8000-000000003301'and g.is_internal and m.screen_id='30000000-0000-4000-8000-000000003301'),1::bigint,'publication alone updates the real direct screen routing');
select set_config('test.source_version_json',(select config_snapshot::text from public.ledscores_goal_alert_versions where id=(current_setting('test.source_moment_published')::jsonb->>'versionId')::uuid),true);
select set_config('test.source_moment_revision',(select revision::text from public.ledscores_goal_alerts where id=current_setting('test.source_moment_id')::uuid),true);
select set_config('test.source_moment_update',public.save_ledscores_moment_design_v2('10000000-0000-4000-8000-000000003301',current_setting('test.source_moment_id')::uuid,current_setting('test.source_moment_revision')::integer,jsonb_set(current_setting('test.source_moment_values')::jsonb,'{screenIds}',jsonb_build_array('30000000-0000-4000-8000-000000003302')),'50000000-0000-4000-8000-000000003343')::text,true);
select is(current_setting('test.source_moment_update')::jsonb->>'outcome','saved','editing direct screen targets saves a new concept');
select is((select count(*)from public.screen_groups where tenant_id='10000000-0000-4000-8000-000000003301'and is_internal),1::bigint,'repeated authoring never creates another hidden group');
select is((select count(*)from public.screen_group_memberships m join public.screen_groups g on g.tenant_id=m.tenant_id and g.id=m.screen_group_id where m.tenant_id='10000000-0000-4000-8000-000000003301'and g.is_internal and m.screen_id='30000000-0000-4000-8000-000000003301'),1::bigint,'changed draft target keeps the current publication on its previous screen');
select is((select config_snapshot::text from public.ledscores_goal_alert_versions where id=(current_setting('test.source_moment_published')::jsonb->>'versionId')::uuid),current_setting('test.source_version_json'),'published immutable version JSON remains byte-for-byte unchanged');
select is((select count(*)from public.screen_group_memberships where tenant_id='10000000-0000-4000-8000-000000003301'and screen_group_id='31000000-0000-4000-8000-000000003301'and screen_id='30000000-0000-4000-8000-000000003301'),1::bigint,'source save never overwrites an existing user group');
